fn putmask(a: Vec<f32>, mask: Vec<bool>, values: Vec<f32>) -> Vec<f32> {
    // Precondition: `a.len() == mask.len()` and `values.len() > 0`
    assert_eq!(
        a.len(),
        mask.len(),
        "Input arrays `a` and `mask` must have the same length"
    );
    let values_len = values.len();
    assert!(
        values_len > 0,
        "`values` must contain at least one replacement element"
    );

    let mut result = Vec::with_capacity(a.len());
    for (i, (elem, flag)) in a.into_iter().zip(mask.into_iter()).enumerate() {
        if flag {
            // Replace with values[i % values_len]
            result.push(values[i % values_len]);
        } else {
            // Keep the original element
            result.push(elem);
        }
    }
    result
}